#nullable enable // autogenerated

using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Pickups;
using MVZ2.GameContent.Seeds;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Contraptions;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Level;
using MVZ2.Vanilla.Pickups;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine;
using PVZEngine.Callbacks;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.nestingTNT)]
    public class NestingTNT : EntityBehaviourDefinition, IExplodeContraptionBehaviour
    {
        public NestingTNT(string nsp, string name) : base(nsp, name)
        {
        }
        void IExplodeContraptionBehaviour.Explode(Entity entity, float range, float damage)
        {
            Explode(entity, range, damage);
        }
        public static DamageOutput[] Explode(Entity entity, float range, float damage)
        {
            var damageEffects = new DamageEffectList(VanillaDamageEffects.MUTE, VanillaDamageEffects.DAMAGE_BODY_AFTER_ARMOR_BROKEN, VanillaDamageEffects.EXPLOSION);
            var damageOutputs = entity.Explode(entity.Position, range, entity.GetFaction(), damage, damageEffects);
            foreach (var output in damageOutputs)
            {
                var result = output.BodyResult;
                if (result != null && result.Fatal)
                {
                    var target = output.Entity;
                    var distance = (target.Position - entity.Position).magnitude;
                    var speed = 25 * Mathf.Lerp(1f, 0.5f, distance / range);
                    target.Velocity = target.Velocity + Vector3.up * speed;
                }
            }
            Explosion.Spawn(entity, entity.GetCenter(), range);
            entity.PlaySound(VanillaSoundID.explosion);
            entity.Level.ShakeScreen(10, 0, 15);

            var blueprintID = GetProduceBlueprintID(entity.GetVariant());
            if (NamespaceID.IsValid(blueprintID))
            {
                SpawnBlueprintPickup(entity, entity.GetCenter(), blueprintID);
            }

            entity.Level.Triggers.RunCallbackFiltered(VanillaLevelCallbacks.POST_CONTRAPTION_DETONATE, new EntityCallbackParams(entity), entity.GetDefinitionID());

            return damageOutputs;
        }
        public static Entity? SpawnBlueprintPickup(Entity entity, Vector3 position, NamespaceID blueprintID)
        {
            var spawnParams = entity.GetSpawnParams();
            spawnParams.SetProperty(VanillaPickupProps.CONTENT_ID, blueprintID);
            spawnParams.SetProperty(BlueprintPickup.PROP_COMMAND_BLOCK, entity.IsImitated());
            return entity.Produce(VanillaPickupID.blueprintPickup, spawnParams);
        }
        public static NamespaceID? GetProduceBlueprintID(int variant)
        {
            if (variant < 0 || variant >= variantProduceBlueprints.Length)
                return null;
            return variantProduceBlueprints[variant];
        }
        public static NamespaceID[] variantProduceBlueprints = new NamespaceID[]
        {
            VanillaBlueprintID.nestingTNTMedium,
            VanillaBlueprintID.nestingTNTSmall,
        };
    }
}
